import{_ as n,a0 as a,w as r,s as i,ao as u,I as p,x as e,a1 as o,A as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"Shotwell 0.15發佈了!添加了更多新功能及修復! | LCTT x X-CMD","titleTemplate":false,"description":"Shotwell 0.15發佈了!添加了更多新功能及修復! | LCTT (201310) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Shotwell 0.15發佈了!添加了更多新功能及修復! | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Shotwell 0.15發佈了!添加了更多新功能及修復! | LCTT (201310) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201310/Shotwell 0.15 released with new features and fixes","title":"Shotwell 0.15發佈了!添加了更多新功能及修復!","tag":"201310","desc":""},"relativePath":"201310/Shotwell 0.15 released with new features and fixes.md","filePath":"[post].md"}'),d={name:"201310/Shotwell 0.15 released with new features and fixes.md"};function h(w,t,f,m,g,S){const l=a("Link");return r(),i("div",null,[t[11]||(t[11]=u(`<h1 id="shotwell-0-15發佈了-添加了更多新功能及修復" tabindex="-1">Shotwell 0.15發佈了!添加了更多新功能及修復! <a class="header-anchor" href="#shotwell-0-15發佈了-添加了更多新功能及修復" aria-label="Permalink to “Shotwell 0.15發佈了!添加了更多新功能及修復!”">​</a></h1><p>Ubuntu 默認安裝了Shotwell，它能輕鬆的管理圖片，提供基本的圖庫管理和圖片編輯功能，以後將提供更多有用的功能.</p><p>Shotwell 已經更新到0.15版本，帶來了新的特徵，修復了大量已知的bug，並進行了更多的優化。</p><p><code>右擊圖片--&gt;打開方式--&gt;Shotwell圖片編輯</code>，用Shotwell打開圖片後，在下邊有幾個選項，其中包括Adjust(調整)選項。</p><p>點擊<code>Adjust</code>按鈕，用户能清楚的發現最新的Highlights(高亮)條目,這對於微調高亮很有幫助；舉例來説，將&#39;Highlights&#39;設置調到很低，這樣就能降低正在編輯的圖片的明暗程度。</p><p><img src="http://iloveubuntu.net/pictures_me/Shotwell%20015%20adjust.jpg" alt=""></p><p>點擊按鈕條中的<code>Crop</code>按鈕，彈出可更改大小的會話框，允許用户根據要求自定義大小裁剪圖片，0.15版本的對話框增加了 <strong>尺寸顯示</strong> 的功能。</p><p>改變會話框的大小，會實時的顯示目前的尺寸大小，用户能自由隨意觀察修剪框中的尺寸；舉個例子，為了得到一張640<em>480的圖片，用户可以將裁剪框調整到640</em>480，在圖片編輯器中便利地增添圖片清晰度。</p><p><img src="http://iloveubuntu.net/pictures_me/Shotwell%20015%20resize%20values.jpg" alt=""></p><p>除此以外,Shotwell 0.15 還增添了:</p><ul><li><p>支持Youtube插件 OAuth/OpenID 認證</p></li><li><p>增強視頻文件的再次導入</p></li><li><p>優化了視頻的縮略圖生成</p></li><li><p>修復了很多漏洞</p></li></ul><p>我們怎麼<strong>安裝</strong> Shotwell 0.15呢?</p><p>添加以下 <strong>官方</strong> PPA(Ubuntu 12.10, Ubuntu 13.04)</p><pre><code>sudo add-apt-repository ppa:yorba/ppa 

sudo apt-get update
sudo apt-get install shotwell
</code></pre><p>Shotwell 0.15已經被放入了Ubuntu 13.10，你只需要定期的更新軟件，便會幫你自動安裝,享受它帶給你的樂趣吧!</p><hr>`,16)),p("p",null,[t[1]||(t[1]=e("via: ",-1)),o(l,{href:"http://iloveubuntu.net/shotwell-015-released-new-features-and-fixes"},{default:s(()=>[...t[0]||(t[0]=[e("http://iloveubuntu.net/shotwell-015-released-new-features-and-fixes",-1)])]),_:1})]),p("p",null,[t[4]||(t[4]=e("本文由 ",-1)),o(l,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[2]||(t[2]=[e("LCTT",-1)])]),_:1}),t[5]||(t[5]=e(" 原創翻譯，",-1)),o(l,{href:"http://linux.cn/"},{default:s(()=>[...t[3]||(t[3]=[e("Linux中國",-1)])]),_:1}),t[6]||(t[6]=e(" 榮譽推出",-1))]),p("p",null,[t[9]||(t[9]=e("譯者：",-1)),o(l,{href:"https://github.com/Luoxcat"},{default:s(()=>[...t[7]||(t[7]=[e("Luoxcat",-1)])]),_:1}),t[10]||(t[10]=e(" 校對：",-1)),o(l,{href:"https://github.com/carolinewuyan"},{default:s(()=>[...t[8]||(t[8]=[e("caroline",-1)])]),_:1})])])}const b=n(d,[["render",h]]);export{C as __pageData,b as default};
